// What Chiron actually persists (localStorage and the `user_data` row).
//
// Built-in content — every curated apostila — is part of the app bundle and
// is regenerated by runSeed() on load. Persisting it too is what broke the
// app: the seed is ~13M characters, several times the 5–10MB localStorage
// quota of Chrome/Firefox/Safari, so the first `setItem` threw and the store
// fell back to an empty document. Only the person's own state is stored here:
// progress over built-in content (mastery, SRS state, sections read), their
// own exercises/cards attached to built-in nodes, and whole sources they
// created (AI-generated in the app, GitHub-ingested).
import type { Card, ChironIndex, ChironLib, Exercise, MapNode, StudySource } from "./types";
import { migrateIndex, migrateLib } from "./migrate";
import { stabilizeIds } from "./stableIds";

export interface ChironData { index: ChironIndex; libs: Record<string, ChironLib> }

type NodeProgress = Pick<MapNode, "mastery" | "lastReviewedAt">;
type CardProgress = Pick<Card, "ease" | "intervalDays" | "dueDate" | "lapses" | "reps">;

export interface PersistedV2 {
  format: 2;
  version: number;
  schemaVersion: number;
  attempts: ChironIndex["attempts"];
  sessions: ChironIndex["sessions"];
  reviewLog: ChironIndex["reviewLog"];
  labProgress: ChironIndex["labProgress"];
  score: ChironIndex["score"];
  /** Sources the person created; with their nodes, cards and libraries. */
  userSources: StudySource[];
  userNodes: MapNode[];
  userCards: Card[];
  userLibs: Record<string, ChironLib>;
  /** Progress over built-in content, keyed by stable id; only non-default entries. */
  builtin: {
    nodes: Record<string, NodeProgress>;
    cards: Record<string, CardProgress>;
    readAt: Record<string, string>;
    extraExercises: Record<string, Exercise[]>;
    removedSources: string[];
  };
}

export function toPersisted(data: ChironData, seed: ChironData): PersistedV2 {
  const seedSources = new Set(seed.index.sources.map((s) => s.id));
  const seedNodes = new Set(seed.index.nodes.map((n) => n.id));
  const seedCards = new Set(seed.index.cards.map((c) => c.id));
  const presentSources = new Set(data.index.sources.map((s) => s.id));

  const builtin: PersistedV2["builtin"] = {
    nodes: {}, cards: {}, readAt: {}, extraExercises: {},
    removedSources: [...seedSources].filter((id) => !presentSources.has(id)),
  };
  for (const node of data.index.nodes) {
    if (seedNodes.has(node.id) && (node.mastery !== 0 || node.lastReviewedAt)) {
      builtin.nodes[node.id] = { mastery: node.mastery, lastReviewedAt: node.lastReviewedAt };
    }
  }
  for (const card of data.index.cards) {
    if (seedCards.has(card.id) && (card.reps > 0 || card.lapses > 0 || card.intervalDays > 0)) {
      builtin.cards[card.id] = { ease: card.ease, intervalDays: card.intervalDays, dueDate: card.dueDate, lapses: card.lapses, reps: card.reps };
    }
  }
  for (const sourceId of seedSources) {
    const lib = data.libs[sourceId];
    if (!lib) continue;
    for (const section of lib.sections) if (section.readAt) builtin.readAt[section.id] = section.readAt;
    const seedExercises = new Set((seed.libs[sourceId]?.exercises ?? []).map((e) => e.id));
    const extra = lib.exercises.filter((e) => !seedExercises.has(e.id));
    if (extra.length) builtin.extraExercises[sourceId] = extra;
  }

  const userSources = data.index.sources.filter((s) => !seedSources.has(s.id));
  const userSourceIds = new Set(userSources.map((s) => s.id));
  const userLibs: Record<string, ChironLib> = {};
  for (const id of userSourceIds) if (data.libs[id]) userLibs[id] = data.libs[id];

  return {
    format: 2,
    version: data.index.version,
    schemaVersion: data.index.schemaVersion,
    attempts: data.index.attempts,
    sessions: data.index.sessions,
    reviewLog: data.index.reviewLog,
    labProgress: data.index.labProgress,
    score: data.index.score,
    userSources,
    // A card the person made on a built-in node is theirs, even though its
    // source is not: only the seed's own nodes/cards are regenerable.
    userNodes: data.index.nodes.filter((n) => !seedNodes.has(n.id)),
    userCards: data.index.cards.filter((c) => !seedCards.has(c.id)),
    userLibs,
    builtin,
  };
}

export function hydrate(saved: PersistedV2, seed: ChironData): ChironData {
  const removed = new Set(saved.builtin.removedSources);
  const sources = seed.index.sources.filter((s) => !removed.has(s.id));
  const live = new Set(sources.map((s) => s.id));
  const userSourceIds = new Set(saved.userSources.map((s) => s.id));
  const keep = (sourceId: string) => live.has(sourceId) || userSourceIds.has(sourceId);

  const nodes = [
    ...seed.index.nodes.filter((n) => live.has(n.sourceId)).map((n) => ({ ...n, ...saved.builtin.nodes[n.id] })),
    ...saved.userNodes.filter((n) => keep(n.sourceId)),
  ];
  const cards = [
    ...seed.index.cards.filter((c) => live.has(c.sourceId)).map((c) => ({ ...c, ...saved.builtin.cards[c.id] })),
    ...saved.userCards.filter((c) => keep(c.sourceId)),
  ];

  const libs: Record<string, ChironLib> = {};
  for (const id of live) {
    const lib = seed.libs[id];
    if (!lib) continue;
    libs[id] = {
      ...lib,
      sections: lib.sections.map((s) => (saved.builtin.readAt[s.id] ? { ...s, readAt: saved.builtin.readAt[s.id] } : s)),
      exercises: [...lib.exercises, ...(saved.builtin.extraExercises[id] ?? [])],
    };
  }
  for (const [id, lib] of Object.entries(saved.userLibs)) libs[id] = migrateLib(lib, id);

  const index = migrateIndex({
    ...seed.index,
    version: saved.version,
    schemaVersion: saved.schemaVersion,
    sources: [...sources, ...saved.userSources],
    nodes,
    cards,
    attempts: saved.attempts,
    sessions: saved.sessions,
    reviewLog: saved.reviewLog,
    labProgress: saved.labProgress ?? [],
    score: saved.score,
  });
  return { index, libs };
}

export function isPersistedV2(value: unknown): value is PersistedV2 {
  return !!value && typeof value === "object" && (value as { format?: unknown }).format === 2;
}

/** Accepts either format: the current one, or the old whole-document
 *  `{index, libs}` with random ids (local data written before 2026-10-23, or
 *  an old cloud row). Old documents are re-keyed with the same natural-key
 *  ids as the seed, so their progress lands on the regenerated content. */
export function restore(value: unknown, seed: ChironData): ChironData {
  if (isPersistedV2(value)) return hydrate(value, seed);
  const old = value as Partial<ChironData> | null;
  if (!old?.index || !Array.isArray(old.index.sources)) return seed;
  const migrated: ChironData = {
    index: migrateIndex(old.index),
    libs: Object.fromEntries(Object.entries(old.libs ?? {}).map(([id, lib]) => [id, migrateLib(lib, id)])),
  };
  return hydrate(toPersisted(stabilizeIds(migrated), seed), seed);
}
